void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   vec2 uv = ( fragCoord - .5* iResolution.xy ) /iResolution.y;
   vec3 col = vec3(0.);
   fragColor = vec4(col,1.0);

    // Blur Parameters
  float samples = 5.0;
  float spacingFactor = .01;

  vec3 result = vec3(0.);
  float fracTime = fract(.4 *  iTime);
  // Loop Over the number of samples
  for(float sa = 0.; sa < samples; sa++)
  {
    float tt = fracTime + sa*spacingFactor/samples;


   // float tt = .5 * iTime;

   vec3 camPos = vec3(0., -2., 12.); 
   vec3 rayDir = normalize(vec3(uv, -1)); 
   float depth = 0.0;

   vec3 p;
   vec3 a1,b1,c1,a2,b2,c2;
   vec3 coord_a, coord_b, coord_c;

   // Raymarching Loop
   for(int numIter = 0; numIter < 90; numIter++){
     p = camPos + depth * rayDir;

     p.yz *= rotation(-PI/4.5);
     p.xz *= rotation(TAU/4. * tt);

     // Domain Repetition    
     float scale = 3.;
     vec2 cellID = clamp(round(scale * p.xz),-5. * scale,5. * scale); 
     p.xz = (scale * p.xz) - cellID;

     // Point calculations        
     vec2 center = cellID / scale;       
     float offC = .5 / scale;  
     float h1a = sin(TAU*tt + 2. * length(center + vec2(-offC , -offC )));
     float h1b = sin(TAU*tt + 2. * length(center + vec2(-offC , +offC )));
     float h1c = sin(TAU*tt + 2. * length(center + vec2(+offC , +offC )));
     float h2b = sin(TAU*tt + 2. * length(center + vec2(+offC , -offC )));

     // Triangle 1
     a1 = vec3(-offC * scale,h1a,-offC * scale);
     b1 = vec3(-offC * scale,h1b,+offC * scale);
     c1 = vec3(+offC * scale,h1c,+offC * scale);

     // Triangle 2
     a2 = c1;
     b2 = vec3(+offC * scale,h2b,-offC * scale);
     c2 = a1;

     // Calculate the SDFs (2x triangles per "quad")
     float t1_SDF = udTriangle(p, a1, b1, c1);
     float t2_SDF = udTriangle(p, a2, b2, c2);

     if (t1_SDF < t2_SDF){
       coord_a = a1;
       coord_b = b1;
       coord_c = c1;
     }
     else{
       coord_a = a2;
       coord_b = b2;
       coord_c = c2;
     }

     float d = min(t1_SDF, t2_SDF);
     depth += d * .4;
     if (d < .01 || depth > 25.0) break;
   }

   if(depth > 25.){
    col = vec3(0.);
   }
   else{
     // Barycentric Coordinates
     float u = length(cross(coord_a - coord_c, p - coord_c)) / 2.;
     float v = length(cross(coord_c - coord_b, p - coord_b)) / 2.;
     float w = length(cross(coord_b - coord_a, p - coord_a)) / 2.;

     // Don't show "quad" diagonal.
     if( abs(v) <= .04 || abs(w) < .04) // || abs(w) < .03){ 
      col = vec3(1.);

     else col = vec3(0.);
   }
       // Add each sample into the into the result
    result += col;                
  }

  // Divide the results by the number of samples
  vec3 colOut = result*1.0/samples;


   fragColor = vec4(colOut,1.0);

}

#define rotation(angle) mat2(cos(angle), -sin(angle), sin(angle), cos(angle));

float PI = 3.14159;
float TAU = 2.*3.14159;

float dot2( in vec3 v ) { return dot(v,v); }

// Thanks IQ!
float udTriangle( vec3 p, vec3 a, vec3 b, vec3 c )
{
  vec3 ba = b - a; vec3 pa = p - a;
  vec3 cb = c - b; vec3 pb = p - b;
  vec3 ac = a - c; vec3 pc = p - c;
  vec3 nor = cross( ba, ac );

  return sqrt(
    (sign(dot(cross(ba,nor),pa)) +
     sign(dot(cross(cb,nor),pb)) +
     sign(dot(cross(ac,nor),pc))<2.0)
     ?
     min( min(
     dot2(ba*clamp(dot(ba,pa)/dot2(ba),0.0,1.0)-pa),
     dot2(cb*clamp(dot(cb,pb)/dot2(cb),0.0,1.0)-pb) ),
     dot2(ac*clamp(dot(ac,pc)/dot2(ac),0.0,1.0)-pc) )
     :
     dot(nor,pa)*dot(nor,pa)/dot2(nor) );
}
